class Order:
    def __init__(self, skus: list[str]) -> None:
        self.lines = [OrderLine(s) for s in skus]

class Cart:
    def __init__(self, pricing: PricingService) -> None:
        self.pricing = pricing

    def total(self, coupon: Coupon) -> float:
        return self.pricing.price(self, coupon)
